    }

    // Cleanup all modules
    for (const [moduleId, wrapper] of this.modules) {
      try {
        if (wrapper.module.cleanup && typeof wrapper.module.cleanup === 'function') {
          await wrapper.module.cleanup();
        }
      } catch (error) {
