        const price = data[data.length - 1];

        if (price < bb.lower) {
          return { action: 'BUY', confidence: 0.6, reason: 'Price below lower Bollinger' };
        } else if (price > bb.upper) {
          return { action: 'SELL', confidence: 0.6, reason: 'Price above upper Bollinger' };
