/**
 * Get the WebSocket URL for a specific service
 * @param {string} service - Service name: 'data', 'gui', 'control', etc.
 * @returns {string} Complete WebSocket URL
 */
function getWebSocketUrl(service) {
  // Check if service exists
  if (!CONFIG.ports[service]) {
    throw new Error(`Unknown WebSocket service: ${service}. Valid services: ${Object.keys(CONFIG.ports).join(', ')}`);
  }

  // Use override if provided
  if (CONFIG.overrideBaseUrl) {
    return `${CONFIG.overrideBaseUrl}:${CONFIG.ports[service]}`;
  }

  // Determine base URL based on environment
  let baseUrl;
  if (CONFIG.environment === 'production') {
    const protocol = CONFIG.useSSL ? 'wss' : 'ws';
    baseUrl = `${protocol}://${CONFIG.productionDomain}`;
  } else {
    // Development always uses localhost
    baseUrl = 'ws://localhost';
  }

  // Return complete URL
  return `${baseUrl}:${CONFIG.ports[service]}`;
}

/**
 * Get all WebSocket URLs as an object
 * @returns {Object} Object with all WebSocket URLs
 */
function getAllWebSocketUrls() {
  const urls = {};
  for (const service in CONFIG.ports) {
    urls[service] = getWebSocketUrl(service);
  }
  return urls;
}

/**
 * Get HTTP URL for a service (useful for REST APIs alongside WebSockets)
 * @param {string} service - Service name
 * @returns {string} Complete HTTP URL
 */
function getHttpUrl(service) {
  const wsUrl = getWebSocketUrl(service);
  return wsUrl.replace('ws://', 'http://').replace('wss://', 'https://');
}

/**
 * Check if we're in production mode
 * @returns {boolean} True if production
 */
function isProduction() {
  return CONFIG.environment === 'production';
}

/**
 * Get current configuration (for debugging)
 * @returns {Object} Current configuration
 */
function getConfig() {
  return {
    ...CONFIG,
    currentUrls: getAllWebSocketUrls()
  };
}

