# /etc/nginx/sites-available/ogzprime
# Complete Nginx configuration for OGZ Prime public access

# Rate limiting zone
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=10r/s;
limit_req_zone $binary_remote_addr zone=ws_limit:10m rate=5r/s;

# Upstream definitions
upstream bot_api {
    server 127.0.0.1:3008;  # Trading bot API
    keepalive 32;
}

upstream ssl_server {
    server 127.0.0.1:3010;  # SSL server with WebSocket
    keepalive 32;
}

# Redirect HTTP to HTTPS
server {
    listen 80;
    listen [::]:80;
    server_name ogzprime.com www.ogzprime.com;

    # Let's Encrypt challenge
    location /.well-known/acme-challenge/ {
        root /var/www/certbot;
    }

    # Redirect all other traffic to HTTPS
    location / {
        return 301 https://$server_name$request_uri;
    }
}

# Main HTTPS server
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name ogzprime.com www.ogzprime.com;

    # SSL certificates (Let's Encrypt)
    ssl_certificate /etc/letsencrypt/live/ogzprime.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/ogzprime.com/privkey.pem;

    # SSL configuration
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers HIGH:!aNULL:!MD5;
    ssl_prefer_server_ciphers on;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;

    # Security headers
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-XSS-Protection "1; mode=block" always;

    # Logging
    access_log /var/log/nginx/ogzprime_access.log;
    error_log /var/log/nginx/ogzprime_error.log;

    # Main dashboard (from SSL server)
    location / {
        proxy_pass http://ssl_server;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Caching for static assets
        location ~* \.(js|css|png|jpg|jpeg|gif|ico|svg)$ {
            proxy_pass http://ssl_server;
            expires 1h;
            add_header Cache-Control "public, immutable";
        }
    }

    # WebSocket endpoint (CRITICAL for real-time data)
    location /ws {
        proxy_pass http://ssl_server/ws;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # WebSocket specific timeouts
        proxy_connect_timeout 7d;
        proxy_send_timeout 7d;
        proxy_read_timeout 7d;

        # Disable buffering for WebSocket
        proxy_buffering off;

        # Rate limiting for WebSocket connections
        limit_req zone=ws_limit burst=10 nodelay;
    }

    # API endpoints from SSL server
    location /api/ {
        proxy_pass http://ssl_server/api/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # API rate limiting
        limit_req zone=api_limit burst=20 nodelay;

        # Timeouts for API
        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
    }

    # Trading bot API (if you want direct access)
    location /bot/ {
        proxy_pass http://bot_api/;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Authentication (optional)
        # auth_basic "Bot Access";
        # auth_basic_user_file /etc/nginx/.htpasswd;
    }

    # Stripe webhooks (if needed)
    location /stripe-webhook {
        proxy_pass http://ssl_server/stripe-webhook;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Stripe requires raw body
        proxy_set_header Content-Type $content_type;
        proxy_set_header X-Stripe-Signature $http_stripe_signature;
    }

    # Health check endpoint
    location /health {
        proxy_pass http://ssl_server/api/health;
        access_log off;
    }

    # Block access to sensitive files
    location ~ /\. {
        deny all;
    }

    # Custom error pages
    error_page 502 503 504 /50x.html;
    location = /50x.html {
        root /usr/share/nginx/html;
    }
}

