  /**
   * CREATE CHART.JS PLUGIN FOR DRAWING LEVELS
   */
  createChartPlugin() {
    const self = this;

    // Create the plugin
    this.levelsPlugin = {
      id: 'dynamicLevels',

      // Draw after datasets but before tooltips
      afterDatasetsDraw(chart) {
        const ctx = chart.ctx;
        const chartArea = chart.chartArea;
        const meta = chart.getDatasetMeta(0);

        if (!chartArea || !self.currentLevels.entry) return;

        ctx.save();

        // Draw Golden Zone first (background)
        if (self.config.goldenZone.enabled && self.currentLevels.goldenZone) {
          self.drawGoldenZone(ctx, chart, self.currentLevels.goldenZone);
        }

        // Draw Support levels
        if (self.config.support.enabled) {
          self.currentLevels.support.forEach(level => {
            self.drawHorizontalLine(ctx, chart, level.price, {
              color: self.config.support.color,
              lineWidth: self.config.support.lineWidth,
              lineDash: self.config.support.lineDash,
              opacity: self.config.support.opacity,
              label: `S: $${level.price.toFixed(0)} (${level.touches}x)`,
              labelSide: 'left'
            });
          });
        }

        // Draw Resistance levels
        if (self.config.resistance.enabled) {
          self.currentLevels.resistance.forEach(level => {
            self.drawHorizontalLine(ctx, chart, level.price, {
              color: self.config.resistance.color,
              lineWidth: self.config.resistance.lineWidth,
              lineDash: self.config.resistance.lineDash,
              opacity: self.config.resistance.opacity,
              label: `R: $${level.price.toFixed(0)} (${level.touches}x)`,
              labelSide: 'right'
            });
          });
        }

        // Draw Fibonacci levels
        if (self.config.fibonacci.enabled) {
          self.currentLevels.fibonacci.forEach(fib => {
            const color = self.config.fibonacci.colors[fib.level] || '#ffffff';
            self.drawHorizontalLine(ctx, chart, fib.price, {
              color: color,
              lineWidth: self.config.fibonacci.lineWidth,
              lineDash: self.config.fibonacci.lineDash,
              opacity: self.config.fibonacci.opacity,
              label: `${(fib.level * 100).toFixed(1)}%: $${fib.price.toFixed(0)}`,
              labelSide: fib.level < 1 ? 'left' : 'right'
            });
          });
        }

        // Draw Entry line
        if (self.config.entry.enabled && self.currentLevels.entry) {
          self.drawHorizontalLine(ctx, chart, self.currentLevels.entry.price, {
            color: self.config.entry.color,
            lineWidth: self.config.entry.lineWidth,
            lineDash: self.config.entry.lineDash,
            opacity: self.config.entry.opacity,
            label: `ENTRY: $${self.currentLevels.entry.price.toFixed(2)}`,
            labelSide: 'center',
            highlight: true
          });
        }

        // Draw Target levels
        if (self.config.targets.enabled) {
          Object.entries(self.currentLevels.targets).forEach(([type, price]) => {
            if (price && self.config.targets.colors[type]) {
              self.drawHorizontalLine(ctx, chart, price, {
                color: self.config.targets.colors[type],
                lineWidth: self.config.targets.lineWidth,
                lineDash: self.config.targets.lineDash,
                opacity: self.config.targets.opacity,
                label: `T-${type}: $${price.toFixed(0)}`,
                labelSide: 'right'
              });
            }
          });
        }

        // Draw Stop levels
        if (self.config.stops.enabled) {
          Object.entries(self.currentLevels.stops).forEach(([type, price]) => {
            if (price && self.config.stops.colors[type]) {
              self.drawHorizontalLine(ctx, chart, price, {
                color: self.config.stops.colors[type],
                lineWidth: self.config.stops.lineWidth,
                lineDash: self.config.stops.lineDash,
                opacity: self.config.stops.opacity,
                label: `SL-${type}: $${price.toFixed(0)}`,
                labelSide: 'left'
              });
            }
          });
        }

        // Draw Trend lines (MAs)
        if (self.config.trendLines.enabled && self.currentLevels.trends) {
          Object.entries(self.currentLevels.trends).forEach(([type, data]) => {
            if (data && data.ma && self.config.trendLines.colors[type]) {
              self.drawHorizontalLine(ctx, chart, data.ma, {
                color: self.config.trendLines.colors[type],
                lineWidth: self.config.trendLines.lineWidth,
                lineDash: [],
                opacity: self.config.trendLines.opacity,
                label: `${type}: $${data.ma.toFixed(0)}`,
                labelSide: 'left'
              });
            }
          });
        }

        ctx.restore();
      }
    };

    // Register the plugin with Chart.js
    if (this.chart) {
      // Check if plugin already registered
      const existingPlugin = Chart.registry.plugins.get('dynamicLevels');
      if (existingPlugin) {
        Chart.registry.plugins.unregister(existingPlugin);
      }

      Chart.register(this.levelsPlugin);

      // Force chart update
      this.chart.update();
    }
  }

  /**
   * DRAW HORIZONTAL LINE WITH LABEL
   */
  drawHorizontalLine(ctx, chart, price, options) {
    const chartArea = chart.chartArea;
    const yScale = chart.scales.y;

    if (!yScale) return;

    const y = yScale.getPixelForValue(price);

    // Don't draw if outside chart area
    if (y < chartArea.top || y > chartArea.bottom) return;

    ctx.save();

    // Set line style
    ctx.globalAlpha = options.opacity || 1;
    ctx.strokeStyle = options.color;
    ctx.lineWidth = options.lineWidth || 1;
    ctx.setLineDash(options.lineDash || []);

    // Draw line
    ctx.beginPath();
    ctx.moveTo(chartArea.left, y);
    ctx.lineTo(chartArea.right, y);
    ctx.stroke();

    // Draw label if specified
    if (options.label) {
      ctx.font = options.highlight ? 'bold 12px Arial' : '10px Arial';
      ctx.fillStyle = options.color;
      ctx.textAlign = options.labelSide === 'center' ? 'center' : 
                     options.labelSide === 'right' ? 'end' : 'start';
      ctx.textBaseline = 'bottom';

      let labelX;
      if (options.labelSide === 'center') {
        labelX = (chartArea.left + chartArea.right) / 2;
      } else if (options.labelSide === 'right') {
        labelX = chartArea.right - 10;
      } else {
        labelX = chartArea.left + 10;
      }

      // Background for label
      const textMetrics = ctx.measureText(options.label);
      const padding = 4;

      ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
      ctx.fillRect(
        labelX - (options.labelSide === 'center' ? textMetrics.width / 2 : 0) - padding,
        y - 12 - padding,
        textMetrics.width + padding * 2,
        12 + padding
      );

      // Draw text
      ctx.fillStyle = options.color;
      ctx.fillText(options.label, labelX, y - 2);
    }

    ctx.restore();
  }

  /**
   * DRAW GOLDEN ZONE (SHADED AREA)
   */
  drawGoldenZone(ctx, chart, zone) {
    const chartArea = chart.chartArea;
    const yScale = chart.scales.y;

    if (!yScale || !zone.upper || !zone.lower) return;

    const yUpper = yScale.getPixelForValue(zone.upper);
    const yLower = yScale.getPixelForValue(zone.lower);

    ctx.save();

    // Draw filled area
    ctx.globalAlpha = this.config.goldenZone.fillOpacity;
    ctx.fillStyle = this.config.goldenZone.color;
    ctx.fillRect(
      chartArea.left,
      Math.max(yUpper, chartArea.top),
      chartArea.right - chartArea.left,
      Math.min(yLower, chartArea.bottom) - Math.max(yUpper, chartArea.top)
    );

    // Draw borders
    ctx.globalAlpha = this.config.goldenZone.borderOpacity;
    ctx.strokeStyle = this.config.goldenZone.color;
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);

    // Upper border
    ctx.beginPath();
    ctx.moveTo(chartArea.left, yUpper);
    ctx.lineTo(chartArea.right, yUpper);
    ctx.stroke();

    // Lower border
    ctx.beginPath();
    ctx.moveTo(chartArea.left, yLower);
    ctx.lineTo(chartArea.right, yLower);
    ctx.stroke();

    // Label
    ctx.font = 'bold 12px Arial';
    ctx.fillStyle = this.config.goldenZone.color;
    ctx.textAlign = 'center';
    ctx.fillText('GOLDEN ZONE', (chartArea.left + chartArea.right) / 2, (yUpper + yLower) / 2);

    ctx.restore();
  }

  /**
   * LISTEN FOR WEBSOCKET UPDATES
   */
  listenForUpdates() {
    // Listen for entry analysis from your bot
    if (this.dashboard && this.dashboard.botSocket) {
      const originalOnMessage = this.dashboard.botSocket.onmessage;

      this.dashboard.botSocket.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);

          if (data.type === 'entry_analysis') {
            this.updateLevels(data.data);
          }

          // Call original handler
          if (originalOnMessage) {
            originalOnMessage.call(this.dashboard.botSocket, event);
          }
        } catch (err) {
          console.error('Parse error:', err);
        }
      };
    }
  }

  /**
   * UPDATE LEVELS FROM WEBSOCKET DATA
   */
  updateLevels(data) {
    console.log('📊 Updating chart levels from entry analysis');

    // Update entry
    if (data.entry) {
      this.currentLevels.entry = data.entry;
    }

    // Update Fibonacci levels
    if (data.fibonacci) {
      this.currentLevels.fibonacci = data.fibonacci;
    }

    // Update Support levels (limit to top 5)
    if (data.support) {
      this.currentLevels.support = data.support.slice(0, 5);
    }

    // Update Resistance levels (limit to top 5)
    if (data.resistance) {
      this.currentLevels.resistance = data.resistance.slice(0, 5);
    }

    // Update Targets
    if (data.targets) {
      this.currentLevels.targets = {
        conservative: data.targets.conservative,
        moderate: data.targets.moderate,
        aggressive: data.targets.aggressive
      };
    }

    // Update Stops
    if (data.stops) {
      this.currentLevels.stops = {
        tight: data.stops.tight,
        normal: data.stops.normal,
        wide: data.stops.wide
      };
    }

    // Update Trends
    if (data.trends) {
      this.currentLevels.trends = {
        shortMA: data.trends.shortTrend,
        mediumMA: data.trends.mediumTrend,
        longMA: data.trends.longTrend
      };
    }

    // Update Golden Zone
    if (data.fibonacci) {
      const fib618 = data.fibonacci.find(f => f.level === 0.618);
      const fib65 = data.fibonacci.find(f => f.level === 0.65);

      if (fib618) {
        this.currentLevels.goldenZone = {
          upper: fib618.price,
          lower: fib65 ? fib65.price : fib618.price * 0.98
        };
      }
    }

    // Redraw chart
    if (this.chart) {
      this.chart.update();
    }

    // Show notification
    this.showLevelNotification(data);
  }

  /**
   * SHOW NOTIFICATION WHEN LEVELS UPDATE
   */
  showLevelNotification(data) {
    if (!data.entry) return;

    const notification = document.createElement('div');
    notification.style.cssText = `
      position: fixed;
      top: 20px;
      right: 20px;
      background: linear-gradient(135deg, rgba(0,255,136,0.9), rgba(0,255,255,0.9));
      color: #000;
      padding: 15px 20px;
      border-radius: 10px;
      box-shadow: 0 0 20px rgba(0,255,136,0.5);
      font-weight: bold;
      z-index: 10000;
      animation: slideIn 0.5s ease;
    `;

    notification.innerHTML = `
      <div style="font-size: 14px; margin-bottom: 5px;">📊 LEVELS CALCULATED</div>
      <div style="font-size: 12px;">Entry: $${data.entry.price.toFixed(2)}</div>
      <div style="font-size: 12px;">Direction: ${data.entry.direction.toUpperCase()}</div>
